from .sdk_common import make_client, sdk_call
NVIDIA_BASE_URL = "https://integrate.api.nvidia.com/v1"

def completion_text(completion):
    choices = getattr(completion, "choices", None)
    if not isinstance(choices, list) or not choices:
        raise AIError("format", "NVIDIA 未回傳有效 choices。")
    if getattr(choices[0], "finish_reason", None) == "length":
        raise AIError("incomplete", "回覆達到長度上限，請縮小問題範圍後再試。")
    message = getattr(choices[0], "message", None)
    return checked_text(getattr(message, "content", None))

class NvidiaProvider:
    def generate(self, prompt):
        with make_client(settings.NVIDIA_API_KEY, "NVIDIA", NVIDIA_BASE_URL) as client:
            completion = sdk_call(lambda: create_completion(client, prompt))
        return completion_text(completion)

def sdk_error(exc):
    if isinstance(exc, openai.APITimeoutError):
        return AIError("timeout", "雲端服務等候逾時，請稍後再試。")
    if isinstance(exc, openai.APIConnectionError):
        return AIError("connection", "無法連線雲端服務，請檢查網路。")
    status = getattr(exc, "status_code", None)
    if status in (401, 403):
        return AIError("auth", "請檢查 API key 與帳號的模型使用權限。")
    if status == 429:
        return AIError("rate_limit", "已達速率或額度限制，請檢查方案並稍後再試。")
    if status == 404:
        return AIError("model", "找不到指定模型，請核對模型 ID 與可用權限。")
    return AIError("api", "雲端 API 回覆錯誤，請檢查服務狀態或設定。")

def sdk_call(operation):
    try:
        return operation()
    except openai.OpenAIError as exc:
        raise sdk_error(exc) from None
    except ValueError:
        raise AIError("json", "雲端服務回覆無法解析，請稍後再試。") from None

def get_provider(name) -> TextProvider:
    provider_class = PROVIDERS.get(name)
    if provider_class is None:
        raise AIError("provider", "不支援的服務來源。")
    return provider_class()

class PromptForm(forms.Form):
    provider = forms.ChoiceField(label="服務來源", choices=PROVIDER_CHOICES)
    prompt = forms.CharField(
        label="你的問題", max_length=2000, strip=True,
        widget=forms.Textarea(attrs={"rows": 6, "maxlength": 2000}),
        help_text="最多 2,000 字元；雲端選項會將內容送至該服務。",
        error_messages={
            "required": "請先輸入問題，不能只輸入空白。",
            "max_length": "問題不可超過 2,000 字元。",
        },
    )

@never_cache
@require_http_methods(["GET", "POST"])
def ai_chat(request):
    form = PromptForm(request.POST if request.method == "POST" else None)
    answer = ""
    if request.method == "POST" and form.is_valid():
        try:
            provider = get_provider(form.cleaned_data["provider"])
            answer = provider.generate(form.cleaned_data["prompt"])
        except AIError as exc:
            form.add_error(None, str(exc))
    return render(request, "mysite/ai_chat.html", {
        "form": form, "answer": answer,
    })

